$ErrorActionPreference='Stop'
$js=@'
let ws;try{
const base="http://127.0.0.1:17447";
const info=await(await fetch(base+"/json/version")).json();
ws=new WebSocket(info.webSocketDebuggerUrl);
await new Promise((ok,no)=>{ws.addEventListener("open",ok,{once:true});ws.addEventListener("error",no,{once:true})});
const urls=["https://www.avito.ru/krasnoyarsk/doma_dachi_kottedzhi/2-k._dom_95_m_7719784354","https://www.avito.ru/krasnoyarsk/doma_dachi_kottedzhi/4-k._kottedzh_120_m_4628254145","https://www.avito.ru/krasnoyarsk/doma_dachi_kottedzhi/6-k._kottedzh_180_m_2689642376","https://www.avito.ru/krasnoyarsk/doma_dachi_kottedzhi/5-k._dom_150_m_7572971653"];
const pend=new Map();let counter=40;
ws.addEventListener("message",e=>{let x=JSON.parse(e.data);if(pend.has(x.id)){pend.get(x.id)(x);pend.delete(x.id)}});
const send=(method,params)=>Promise.race([new Promise(resolve=>{let id=++counter;pend.set(id,resolve);ws.send(JSON.stringify({id,method,params}))}),new Promise((_,reject)=>setTimeout(()=>reject(Error("CDP_TIMEOUT")),3200))]);
const out=[];
for(let url of urls){try{let x=await send("Target.createTarget",{url,background:true,newWindow:false});out.push({url,id:x.result?.targetId||null,error:x.error?.code||null})}catch(e){out.push({url,error:"TIMEOUT"})}}
console.log(JSON.stringify(out))
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,100)}))}
if(ws)ws.close();process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'pc-avito-open-selected.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue -Force}
